import{GRADES,CONTENT}from '/data.js';import{renderTool}from '/tools.js';const state={grade:'all',topicId:null,};const $=(sel)=>document.querySelector(sel);const $$=(sel)=>document.querySelectorAll(sel);function escapeHtml(s){return(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function buildGradePills(){const wrap=$('#gradePicker');for(const g of GRADES){const b=document.createElement('button');b.className='grade-pill';b.dataset.grade=g.id;b.textContent=g.short;b.title=g.label;b.setAttribute('role','tab');b.setAttribute('aria-selected','false');b.addEventListener('click',()=>selectGrade(g.id));wrap.appendChild(b)}const all=document.createElement('button');all.className='grade-pill';all.dataset.grade='all';all.textContent='All';all.title='Show all grades';all.setAttribute('role','tab');all.setAttribute('aria-selected','true');all.addEventListener('click',()=>selectGrade('all'));wrap.insertBefore(all,wrap.firstChild);syncActivePill()}function syncActivePill(){$$('.grade-pill').forEach(b=>{const active=b.dataset.grade===state.grade;b.classList.toggle('active',active);if(b.getAttribute('aria-selected')!=null){b.setAttribute('aria-selected',String(active))}})}function selectGrade(gid){state.grade=gid;state.topicId=null;syncActivePill();renderTopicList();renderContent()}function topicsForCurrentGrade(){const items=[];for(const g of GRADES){if(state.grade!=='all'&&g.id!==state.grade)continue;const block=CONTENT[g.id];if(!block)continue;for(const t of block.topics){items.push({grade:g,topic:t})}}return items}function renderTopicList(){const list=$('#topicList');list.innerHTML='';const items=topicsForCurrentGrade();if(!state.topicId&&items[0])state.topicId=items[0].topic.id;else if(state.topicId&&!items.some(it=>it.topic.id===state.topicId)){state.topicId=items[0]?.topic.id||null}for(const{grade,topic}of items){const row=document.createElement('div');row.className='topic-item';if(topic.id===state.topicId)row.classList.add('active');row.dataset.topic=topic.id;row.setAttribute('role','tab');row.setAttribute('tabindex','0');row.setAttribute('aria-selected',String(topic.id===state.topicId));row.innerHTML=`<span>${escapeHtml(topic.title)}</span><span class="badge">${escapeHtml(grade.short)}</span>`;const activate=()=>{state.topicId=topic.id;$$('.topic-item').forEach(el=>{const isActive=el.dataset.topic===topic.id;el.classList.toggle('active',isActive);el.setAttribute('aria-selected',String(isActive))});renderContent()};row.addEventListener('click',activate);row.addEventListener('keydown',(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}});list.appendChild(row)}}function findTopic(tid){for(const g of GRADES){const block=CONTENT[g.id];if(!block)continue;for(const t of block.topics){if(t.id===tid)return{grade:g,topic:t}}}return null}function renderContent(){const c=$('#content');if(!state.topicId){c.innerHTML=`<div class="placeholder"><h2>Pick a topic to start learning</h2><p>Use the grade selector above to filter,then pick a topic on the left.</p></div>`;return}const found=findTopic(state.topicId);if(!found){c.innerHTML=`<div class="placeholder"><h2>Topic not found</h2></div>`;return}const{grade,topic}=found;const formulasHtml=topic.formulas.map(f=>`<div class="formula-card"><h4>${escapeHtml(f.name)}</h4><div class="expr">${escapeHtml(f.formula)}</div><p>${escapeHtml(f.description)}</p></div>`).join('');const skillsHtml=topic.skills.map(s=>`<div class="skill">${escapeHtml(s)}</div>`).join('');const toolHtml=topic.tool?`<div class="tool-card"><h3>Try it</h3><p>Hands-on practice for this topic.</p><div id="toolRoot"></div></div>`:'';c.innerHTML=`<div class="topic-head"><h2>${escapeHtml(topic.title)}</h2><p>${escapeHtml(topic.blurb)}</p><span class="meta">${escapeHtml(grade.label)}· ${escapeHtml(grade.short)}</span></div>${formulasHtml?`<div class="section-title">Formulas</div><div class="formula-grid">${formulasHtml}</div>`:''}${skillsHtml?`<div class="section-title">Skills to practice</div><div class="skills">${skillsHtml}</div>`:''}${toolHtml}`;if(topic.tool)renderTool(topic.tool,$('#toolRoot'))}function setupSignIn(){const btn=$('#signInBtn');const modal=$('#signinModal');const form=$('#signinForm');const cancelBtn=$('#signinCancel');const err=$('#signinError');const open=()=>{err.hidden=true;err.textContent='';modal.hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#signinUser').focus(),50)};const close=()=>{modal.hidden=true;document.body.style.overflow=''};btn.addEventListener('click',open);cancelBtn.addEventListener('click',close);modal.addEventListener('click',(e)=>{if(e.target===modal)close()});document.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&!modal.hidden)close()});form.addEventListener('submit',async(e)=>{e.preventDefault();const u=$('#signinUser').value.trim().toLowerCase();const p=$('#signinPass').value;err.hidden=true;btn.disabled=true;try{const r=await fetch('/api/_unlock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({u,p}),});if(!r.ok)throw new Error('denied');const data=await r.json();if(!data?.path||!data.ok)throw new Error('denied');close();window.location.href=data.path}catch(_e){err.textContent='Sign-in failed.Try again or create an account later.';err.hidden=false}finally{btn.disabled=false}})}document.addEventListener('DOMContentLoaded',()=>{buildGradePills();renderTopicList();renderContent();setupSignIn()});